/* Mature-crop operations are a separate endpoint demonstration, never inferred
   from 28-day seedling data. All grain counts and weighing values are synthetic. */
(()=>{'use strict';const TAU=Math.PI*2,E=CultureEquipment,M=CultureModels,ops=['成熟采穗','剥苞脱粒','分组数粒','空盘去皮','称千粒重'];
const weights=Array.from({length:1000},(_,i)=>.3+(i%2?-1:1)*(Math.floor(i/2)%21)*.001),trayMass=32.45;
function measure(count=1000,{tared=false,loaded=true,moisture=14,target=14}={}){if(!Number.isInteger(count)||count<0||count>1000||!Number.isFinite(moisture)||!Number.isFinite(target)||moisture<0||moisture>=100||target<0||target>=100)throw Error('Invalid grain measurement');const mass=weights.slice(0,count).reduce((s,x)=>s+x,0),grain=loaded?mass:0,reading=grain+(tared?0:trayMass),tkw=count?mass/count*1000:null;return {count,mass,reading,trayMass,tkw,correctedTkw:tkw===null?null:tkw*(100-moisture)/(100-target),moisture,target,tared,loaded}}
function install(){for(const type of M.types){const i=M.steps[type].length-2;M.steps[type][i]=['成熟收获与千粒重','从采玉米穗，到天平上的千粒重','成熟采穗 → 脱粒混匀 → 随机数粒 → 去皮称重',['成熟收获属于另设的全生育期终点；原 28 天苗期测定与成熟籽粒不是同一份观测。','每个独立盆或系统分别收穗、脱粒、混匀，再随机数取 1000 粒；不可只挑大粒。','空盘去皮后装样，稳定读数；比较千粒重时统一含水率，界面称量为教学模拟。']];M.steps[type][i+1]=['计算与解释','核对千粒重记录，再比较磷效应','千粒重 = 样品净重 ÷ 粒数 × 1000',['本次记录来自教学称量操作，不是实际试验结果；先核对粒数、去皮、净重与含水率。','真实磷效应需按独立盆分别测定并分析重复误差，不能凭一次称量或一根玉米穗下结论。','原 28 天苗期吸磷示例单独展开，不能当作成熟籽粒数据。']];}}
function tray(w,x,y,z,width=3,depth=2){w.box(x,y,z,width,.09,depth,'#b9c7ac');for(const zz of [z-depth/2,z+depth/2])w.box(x,y+.09,zz,width,.12,.06,'#d8e0cc');for(const xx of [x-width/2,x+width/2])w.box(xx,y+.09,z,.06,.12,depth,'#d8e0cc')}
function cob(w,x,y,z,options={}){return E.cornCob(w,x,y,z,options)}
function mature(w,x,y,z){MaizeUptake.drawPlant(w,{x,y,z,scale:.95,shootScale:1.15,roots:false});cob(w,x+.38,y+1.45,z,{scale:.5,husk:true});w.line([[x,y+1.5,z],[x+.38,y+1.45,z]],'#82905c',3);for(let i=0;i<8;i++){const a=i/8*TAU;w.line([[x,y+3.5,z],[x+Math.cos(a)*.35,y+3.8,z+Math.sin(a)*.35]],'#bca977',1.4)}w.line([[x,y+3.4,z],[x,y+4.1,z]],'#b19e6c',2);}
function draw(w,s){const op=s.operation||0;if(typeof HydroLab!=='undefined')HydroLab.bench(w,s);else w.box(0,-.23,0,12.8,.22,7,'#465653');if(op===0){const top=E.pot(w,-2.9,.02,0,s.type,{r:1.2,height:1.4});mature(w,-2.9,top,0);tray(w,2.8,.03,0,3.7,2.4);cob(w,1.6,.49,0,{scale:.9,husk:false,lying:true});w.arrow([-.8,2.7,0],[1.5,1.7,0],'#8ca07e');w.label([-2.9,5.6,0],'成熟期 · 玉米穗',{size:15,pill:true});w.label([2.8,2.6,0],'按盆编号，分别采穗',{size:14,pill:true});}
else if(op===1){tray(w,-2.7,.03,0,3.2,2.4);cob(w,-3.8,.53,0,{scale:1,husk:false,lying:true});w.leaf([-3,.2,0],[-4.3,.3,1],.3,'#b7aa76');w.leaf([-3,.2,0],[-1.8,.25,1],.3,'#b9ac75');tray(w,2.5,.03,0,3.6,2.4);for(let i=0;i<100;i++)E.kernel(w,1.06+((i*.6180339)%1)*2.9,.16+(i%4)*.008,-.91+((i*.7548777)%1)*1.83,{size:.15});for(let i=0;i<18;i++){const f=(w.time*.16+i/18)%1;E.kernel(w,-2+f*3.4,.6+Math.sin(f*Math.PI)*.7,-.2+Math.sin(i)*.2,{size:.12})}w.label([-2.7,2.75,0],'剥去苞叶 · 分盆脱粒',{size:14,pill:true});w.label([2.5,1.45,0],'整份籽粒混匀，再随机取样',{size:13,pill:true});}
else if(op===2){const count=s.grainCount||0;for(let group=0;group<10;group++){const gx=(group%5-2)*2.15,gz=(Math.floor(group/5)-.5)*2.8;tray(w,gx,.03,gz,1.85,2.25);const n=Math.max(0,Math.min(100,count-group*100));for(let i=0;i<n;i++)E.kernel(w,gx-.76+(i%10)*.168,.18,gz-.93+Math.floor(i/10)*.2,{size:.09});w.label([gx,.12,gz-1.25],`${group+1} / 10 · ${n} 粒`,{size:9,pill:true});}w.label([0,2,0],`10 组 × 100 粒　已数 ${count} / 1000`,{size:17,pill:true,color:'#7b8353'});}
else{const loaded=op===4&&!!s.grainLoaded,m=measure(s.grainCount||1000,{loaded,tared:!!s.grainTared,moisture:s.grainMoisture??14});const pan=E.balance(w,1.8,.03,0,{value:(loaded?m.reading*Math.min(1,Math.max(0,w.time-(s.grainSettleStart||0))/.9):m.reading).toFixed(2),unit:'g',stable:!loaded||w.time-(s.grainSettleStart||0)>=.9});w.cylinder(1.8,pan.panY,pan.panZ,.83,.17,'#e1e5d6',{n:32,open:true});E.ring(w,1.8,pan.panY+.17,pan.panZ,.83,'#d4dcca',2);if(loaded)for(let i=0;i<m.count;i++){const layer=Math.floor(i/100),j=i%100,a=j*2.399+layer*.73,rr=.71*Math.sqrt((j+.5)/100);if(layer<7&&j>18)continue;E.kernel(w,1.8+Math.cos(a)*rr,pan.panY+.05+layer*.026,pan.panZ+Math.sin(a)*rr,{size:.075})}tray(w,-3,.03,0,3.2,2.4);for(let i=0;i<(loaded?0:100);i++)E.kernel(w,-4.3+(i%10)*.28,.16,-.85+Math.floor(i/10)*.18,{size:.11});w.label([1.8,1.65,0],loaded?(w.time-(s.grainSettleStart||0)<.9?'读数稳定中…':s.grainTared?`净重 ${m.mass.toFixed(2)} g`:'尚未去皮：显示盘 + 样品总重'):(s.grainTared?'空盘去皮完成：0.00 g':`空盘质量 ${trayMass.toFixed(2)} g`),{size:15,pill:true,color:'#578466'});}
if(op<3)w.label([0,-.65,2.8],'成熟期操作演示 · 与 28 天苗期数据分开记录',{size:11,pill:true,color:'#919c80'});w.canvas.dataset.harvestOperation=op;}
install();const previousDraw=CultureWorlds.draw;CultureWorlds.draw=(w,s)=>{const i=M.steps[s.type].length-2;if(s.step===i)return draw(w,s);if(s.step===i+1){const r=s.grainRecord;return draw(w,{...s,operation:r?4:3,grainCount:r?.count||1000,grainTared:!!r,grainLoaded:!!r,grainSettleStart:-10,grainMoisture:r?.moisture??14})}return previousDraw(w,s)};const get=CulturePractical.get;CulturePractical.get=(type,step)=>step===M.steps[type].length-2?ops:get(type,step);
window.MaizeHarvest={ops,weights,trayMass,measure,draw};
})();




